ON DUPLICATE KEY UPDATE name=VALUES(name),description=VALUES(description),active=1;

ON DUPLICATE KEY UPDATE full_name=VALUES(full_name),password_hash=VALUES(password_hash),role=VALUES(role),status='ACTIVE';

ON DUPLICATE KEY UPDATE preferred_language=VALUES(preferred_language);

ON DUPLICATE KEY UPDATE primary_category_id=VALUES(primary_category_id),verification_status=VALUES(verification_status),trust_score=VALUES(trust_score),active=1;

ON DUPLICATE KEY UPDATE skill_name=VALUES(skill_name);

ON DUPLICATE KEY UPDATE is_primary=VALUES(is_primary);

ON DUPLICATE KEY UPDATE emergency_available=VALUES(emergency_available);

ON DUPLICATE KEY UPDATE area_name=VALUES(area_name);

ON DUPLICATE KEY UPDATE estimated_min=VALUES(estimated_min),estimated_max=VALUES(estimated_max),active=1;

ON DUPLICATE KEY UPDATE status=VALUES(status),updated_at=VALUES(updated_at);








